181	export function internal_set(source, value, updated_during_traversal = null) {
182		if (!source.equals(value)) {
183			var old_value = source.v;
184	
185			if (is_destroying_effect) {
186				old_values.set(source, value);
187			} else {
188				old_values.set(source, old_value);
189			}
190	
191			source.v = value;
192	
193			var batch = Batch.ensure();
194			batch.capture(source, old_value);
195	
196			if (DEV) {
197				if (tracing_mode_flag || active_effect !== null) {
198					source.updated ??= new Map();
199	
200					// For performance reasons, when not using $inspect.trace, we only start collecting stack traces
201					// after the same source has been updated more than 5 times in the same flush cycle.
202					const count = (source.updated.get('')?.count ?? 0) + 1;
203					source.updated.set('', { error: /** @type {any} */ (null), count });
204	
205					if (tracing_mode_flag || count > 5) {
206						const error = get_error('updated at');
207	
208						if (error !== null) {
209							let entry = source.updated.get(error.stack);
210	
211							if (!entry) {
212								entry = { error, count: 0 };
213								source.updated.set(error.stack, entry);
214							}
215	
216							entry.count++;
217						}
218					}
219				}
220	
221				if (active_effect !== null) {
222					source.set_during_effect = true;
223				}
224			}
225	
226			if ((source.f & DERIVED) !== 0) {
227				const derived = /** @type {Derived} */ (source);
228	
229				// if we are assigning to a dirty derived we set it to clean/maybe dirty but we also eagerly execute it to track the dependencies
230				if ((source.f & DIRTY) !== 0) {
231					execute_derived(derived);
232				}
233	
234				update_derived_status(derived);
235			}
236	
237			source.wv = increment_write_version();
238	
239			// For debugging, in case you want to know which reactions are being scheduled:
240			// log_reactions(source);
241			mark_reactions(source, DIRTY, updated_during_traversal);
242	
243			// It's possible that the current reaction might not have up-to-date dependencies
244			// whilst it's actively running. So in the case of ensuring it registers the reaction
245			// properly for itself, we need to ensure the current effect actually gets
246			// scheduled. i.e: `$effect(() => x++)`
247			if (
248				is_runes() &&
249				active_effect !== null &&
250				(active_effect.f & CLEAN) !== 0 &&
251				(active_effect.f & (BRANCH_EFFECT | ROOT_EFFECT)) === 0
252			) {
253				if (untracked_writes === null) {
254					set_untracked_writes([source]);
255				} else {
256					untracked_writes.push(source);
257				}
258			}
259	
260			if (!batch.is_fork && eager_effects.size > 0 && !eager_effects_deferred) {
261				flush_eager_effects();
262			}
263		}
264	
265		return value;
266	}
