268	export function flush_eager_effects() {
269		eager_effects_deferred = false;
270	
271		for (const effect of eager_effects) {
272			// Mark clean inspect-effects as maybe dirty and then check their dirtiness
273			// instead of just updating the effects - this way we avoid overfiring.
274			if ((effect.f & CLEAN) !== 0) {
275				set_signal_status(effect, MAYBE_DIRTY);
276			}
277	
278			if (is_dirty(effect)) {
279				update_effect(effect);
280			}
281		}
282	
283		eager_effects.clear();
284	}
